from pwn import *

# Initialize binary
binary = ELF('/home/ctfplayer/ctf_files/kvm/challenge')

# Find KVM-related symbols and strings
print("[ ] Analyzing binary for KVM setup...")
for sym in binary.symbols:
    if 'kvm' in sym.lower():
        print(f"[+] Found KVM symbol: {sym} at {hex(binary.symbols[sym])}")

print("\n[ ] Looking for interesting strings...")
found_strings = []
for section in binary.sections:
    if section.name in ['.rodata', '.data']:
        try:
            data = binary.read(section.header.sh_addr, section.header.sh_size)
            strings = data.split(b'\x00')
            for s in strings:
                if len(s) > 4:  # Filter out very short strings
                    try:
                        decoded = s.decode()
                        if any(x in decoded.lower() for x in ['kvm', 'vm', 'correct', 'wrong', 'flag']):
                            found_strings.append(decoded)
                            print(f"[+] Found string: {decoded}")
                    except:
                        pass
        except:
            pass

print("\n[ ] Analyzing .payload section...")
try:
    payload_section = binary.get_section_by_name('.payload')
    if payload_section:
        print(f"[+] .payload section found at {hex(payload_section.header.sh_addr)}")
        print(f"[+] Size: {hex(payload_section.header.sh_size)}")
        print(f"[+] Flags: {hex(payload_section.header.sh_flags)}")
except:
    print("[-] No .payload section found")

print("\n[ ] Looking for memory mappings...")
try:
    elf_text = binary.read(binary.get_section_by_name('.text').header.sh_addr, 
                          binary.get_section_by_name('.text').header.sh_size)
    # Look for common KVM syscall numbers
    kvm_create_vm = elf_text.find(b'\xBA\xA0\x00\x00\x00')  # mov edx, 0xa0 (KVM_CREATE_VM)
    kvm_set_user_memory = elf_text.find(b'\xBA\x46\x00\x00\x00')  # mov edx, 0x46 (KVM_SET_USER_MEMORY_REGION)
    kvm_set_regs = elf_text.find(b'\xBA\x87\x00\x00\x00')  # mov edx, 0x87 (KVM_SET_REGS)

    if kvm_create_vm != -1:
        print(f"[+] Found KVM_CREATE_VM at offset: {hex(kvm_create_vm)}")
    if kvm_set_user_memory != -1:
        print(f"[+] Found KVM_SET_USER_MEMORY_REGION at offset: {hex(kvm_set_user_memory)}")
    if kvm_set_regs != -1:
        print(f"[+] Found KVM_SET_REGS at offset: {hex(kvm_set_regs)}")
except:
    print("[-] Error analyzing text section")

