from pwn import *
import struct

context.arch = 'amd64'
context.log_level = 'debug'

def dump_binary_info():
    binary = ELF('/home/ctfplayer/ctf_files/kvm/challenge')

    # Get all sections
    print("=== Sections ===")
    for section in binary.sections:
        try:
            name = section.name
            addr = section.header.sh_addr
            size = section.header.sh_size
            print(f"{name}: addr=0x{addr:x}, size=0x{size:x}")

            # Special handling for .payload section
            if name == '.payload':
                data = section.data()
                print("\nPayload data:")
                print(hexdump(data))

                # Try to decode as x86 instructions
                print("\nAttempting to disassemble payload:")
                try:
                    for insn in disasm(data):
                        print(f"0x{insn.address:x}:\t{insn.mnemonic}\t{insn.op_str}")
                except:
                    print("Failed to disassemble - might not be x86 code")
        except:
            continue

    # Search for useful strings
    print("\n=== Strings ===")
    for section in binary.sections:
        try:
            data = section.data()
            strings = data.split(b'\x00')
            for s in strings:
                if len(s) > 4:  # Filter out very short strings
                    try:
                        decoded = s.decode()
                        if any(x in decoded.lower() for x in ['kvm', 'flag', 'key', 'password', 'secret']):
                            print(f"Found string: {decoded}")
                    except:
                        continue
        except:
            continue

    # Look for specific KVM-related constants
    kvm_constants = {
        0x0000AE00: "KVM_GET_API_VERSION",
        0x0000AE01: "KVM_CREATE_VM",
        0x0000AE03: "KVM_CREATE_VCPU",
        0x0000AE80: "KVM_GET_VCPU_MMAP_SIZE",
        0x0000AE81: "KVM_RUN",
        0x0000AE82: "KVM_GET_REGS",
        0x0000AE83: "KVM_SET_REGS",
        0x0000AE84: "KVM_GET_SREGS",
        0x0000AE85: "KVM_SET_SREGS"
    }

    print("\n=== KVM Constants ===")
    for section in binary.sections:
        try:
            data = section.data()
            for i in range(0, len(data)-4, 4):
                val = struct.unpack("<I", data[i:i+4])[0]
                if val in kvm_constants:
                    print(f"Found KVM constant at offset 0x{i:x}: {kvm_constants[val]} (0x{val:x})")
        except:
            continue

dump_binary_info()
